insert into passages (id, text, difficulty_level, b, active) values
('3eaf782c-dfda-4fca-a9f2-09089fbc7306', 'Many schools around the world have begun introducing coding classes as part of their standard curriculum, starting as early as elementary school. Supporters of this trend argue that learning to code helps children develop problem-solving skills and logical thinking that are useful far beyond computer programming itself. Some educators also point out that coding teaches persistence, since students must learn to identify and fix errors in their programs, a process often called debugging. Critics, however, worry that adding coding classes takes time away from other important subjects, such as art and physical education, especially in schools with limited class hours. To address this concern, some schools have chosen to integrate basic coding concepts into existing subjects, such as math and science, rather than creating an entirely separate class.', 2, -1.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('7c864f2c-6361-4bd9-a018-1ab33b32fbb0', 'sentence_completion', 'The team celebrated after they finally ___ the difficult project on time.', NULL, '[{"id": "b", "text": "completed"}, {"id": "c", "text": "forgot"}, {"id": "d", "text": "postponed"}, {"id": "a", "text": "abandoned"}]'::jsonb, 0, '{"strategy": "celebrated after finally = חגגו אחרי סוף סוף. מה עושים כשמסיימים פרויקט קשה?", "correct_reason": "completed = השלימו. חגיגה מגיעה אחרי השלמה.", "options_analysis": ["נכון! completed = השלימו — מתאים לחגיגה בזמן", "forgot = שכחו — לא רלוונטי לחגיגה", "postponed = דחו — סותר ''on time''", "abandoned = ננטש — סותר חגיגה"]}', 1.45, -1.0, 0.25, 2, 'ai', NULL, true),
('599d9f22-b074-4c16-8f3d-3f1a2b4cd14a', 'sentence_completion', 'She was ___ when her manager praised her work in front of everyone.', NULL, '[{"id": "a", "text": "embarrassed"}, {"id": "c", "text": "proud"}, {"id": "b", "text": "angry"}, {"id": "d", "text": "bored"}]'::jsonb, 1, '{"strategy": "praised her work = שיבח את עבודתה. איך מרגישים משבח פומבי?", "correct_reason": "proud = גאה. שבח פומבי גורם לגאווה.", "options_analysis": ["embarrassed = נבוכה — אפשרי אך פחות מתאים מ''proud'' לשבח", "נכון! proud = גאה — תגובה טבעית לשבח", "angry = כועסת — לא קשור לשבח", "bored = משועממת — הפוך משבח"]}', 1.32, -1.0, 0.25, 2, 'ai', NULL, true),
('e1ab4793-699b-4ab6-a4c5-1d04bedc237b', 'sentence_completion', 'The company decided to ___ its old computers with newer models.', NULL, '[{"id": "c", "text": "repair"}, {"id": "b", "text": "ignore"}, {"id": "a", "text": "replace"}, {"id": "d", "text": "sell"}]'::jsonb, 2, '{"strategy": "old computers...newer models = מחשבים ישנים...דגמים חדשים. מה עושים עם ישן כדי לקבל חדש?", "correct_reason": "replace = להחליף. מחליפים ישן בחדש.", "options_analysis": ["repair = לתקן — פחות מתאים ל''newer models''", "ignore = להתעלם מ- — לא רלוונטי", "נכון! replace = להחליף — מתאים למעבר לדגמים חדשים", "sell = למכור — לא מסביר קבלת דגמים חדשים"]}', 1.03, -1.0, 0.25, 2, 'ai', NULL, true),
('b1a1698f-66d0-4da2-8b63-6553f5d2b2f6', 'sentence_completion', 'The students were asked to ___ quiet while the test was in progress.', NULL, '[{"id": "b", "text": "forget"}, {"id": "c", "text": "leave"}, {"id": "d", "text": "become"}, {"id": "a", "text": "remain"}]'::jsonb, 3, '{"strategy": "while the test was in progress = בזמן שהמבחן מתקיים. מה מבקשים מתלמידים במבחן?", "correct_reason": "remain = להישאר. מבקשים להישאר שקטים.", "options_analysis": ["forget = לשכוח — לא רלוונטי", "leave = לעזוב — סותר את הישארות בכיתה", "become = להפוך — פחות טבעי מ''remain quiet''", "נכון! remain = להישאר — מתאים לבקשה להישאר שקטים"]}', 1.46, -1.0, 0.25, 2, 'ai', NULL, true),
('8e6e0c75-f044-43a7-aa53-2fd5beab8218', 'sentence_completion', 'The mechanic ___ the strange noise to a loose part in the engine.', NULL, '[{"id": "b", "text": "traced"}, {"id": "c", "text": "celebrated"}, {"id": "a", "text": "ignored"}, {"id": "d", "text": "forgot"}]'::jsonb, 0, '{"strategy": "the strange noise = הרעש המוזר. מה עושה מוסכניק כדי למצוא מקור רעש?", "correct_reason": "traced = התחקה אחר/איתר. מוסכניק מאתר את מקור הרעש.", "options_analysis": ["נכון! traced = איתר — פעולה טבעית של מוסכניק", "celebrated = חגג — לא רלוונטי", "ignored = התעלם מ- — סותר את הצורך לתקן", "forgot = שכח — לא רלוונטי לתיקון"]}', 1.28, -1.0, 0.25, 2, 'ai', NULL, true),
('6b3aea4e-7047-48e7-928f-5ca6f1ce217a', 'sentence_completion', 'The charity organized a fundraiser to ___ money for flood victims.', NULL, '[{"id": "a", "text": "spend"}, {"id": "b", "text": "raise"}, {"id": "c", "text": "waste"}, {"id": "d", "text": "hide"}]'::jsonb, 1, '{"strategy": "fundraiser = אירוע גיוס כספים. מה מטרת אירוע כזה?", "correct_reason": "raise = לגייס/להעלות. אירוע גיוס כספים נועד לגייס כסף.", "options_analysis": ["spend = להוציא — לא מטרת גיוס כספים", "נכון! raise = לגייס — המטרה הטבעית של ''fundraiser''", "waste = לבזבז — הפוך ממטרת עזרה", "hide = להסתיר — לא רלוונטי"]}', 1.04, -1.0, 0.25, 2, 'ai', NULL, true),
('f2b7db2b-b53f-4906-9f15-b5b42c1f8f20', 'sentence_completion', 'The hikers had to ___ their route because of the fallen tree blocking the path.', NULL, '[{"id": "c", "text": "enjoy"}, {"id": "a", "text": "forget"}, {"id": "b", "text": "change"}, {"id": "d", "text": "continue"}]'::jsonb, 2, '{"strategy": "blocking the path = חוסם את השביל. מה עושים כשמסלול חסום?", "correct_reason": "change = לשנות. חסימה מחייבת שינוי מסלול.", "options_analysis": ["enjoy = ליהנות מ- — לא רלוונטי לחסימה", "forget = לשכוח — לא רלוונטי", "נכון! change = לשנות — פתרון הגיוני לחסימה", "continue = להמשיך — סותר חסימת שביל"]}', 1.02, -1.0, 0.25, 2, 'ai', NULL, true),
('7dc1cd1f-095d-489a-8878-12959b7d2c28', 'sentence_completion', 'The manager was ___ when the project was finished two weeks early.', NULL, '[{"id": "b", "text": "angry"}, {"id": "c", "text": "confused"}, {"id": "d", "text": "disappointed"}, {"id": "a", "text": "delighted"}]'::jsonb, 3, '{"strategy": "finished two weeks early = הסתיים שבועיים מוקדם. איך מרגיש מנהל מפרויקט שהושלם מוקדם?", "correct_reason": "delighted = שמח מאוד. סיום מוקדם משמח מנהל.", "options_analysis": ["angry = כועס — הפוך מתגובה חיובית", "confused = מבולבל — לא קשור", "disappointed = מאוכזב — הפוך מתגובה לסיום מוקדם", "נכון! delighted = שמח מאוד — תגובה טבעית לסיום מוקדם"]}', 1.05, -1.0, 0.25, 2, 'ai', NULL, true),
('6a9754c1-3dd2-40c2-b870-610eb8ca8bfc', 'sentence_completion', 'The scientists were able to ___ the cause of the mysterious illness.', NULL, '[{"id": "b", "text": "identify"}, {"id": "c", "text": "forget"}, {"id": "d", "text": "ignore"}, {"id": "a", "text": "hide"}]'::jsonb, 0, '{"strategy": "the mysterious illness = המחלה המסתורית. מה עושים מדענים עם סיבה לא ידועה?", "correct_reason": "identify = לזהות. מדענים מזהים סיבות למחלות.", "options_analysis": ["נכון! identify = לזהות — פעולה טבעית של מדענים", "forget = לשכוח — לא רלוונטי", "ignore = להתעלם מ- — סותר מחקר על מחלה", "hide = להסתיר — הפוך ממטרת מחקר"]}', 1.23, -1.0, 0.25, 2, 'ai', NULL, true),
('60d2014f-df00-4102-9fe1-8c2be01e74fd', 'sentence_completion', 'The company''s new app ___ users to track their daily exercise.', NULL, '[{"id": "b", "text": "ignores"}, {"id": "d", "text": "allows"}, {"id": "c", "text": "forbids"}, {"id": "a", "text": "prevents"}]'::jsonb, 1, '{"strategy": "track their daily exercise = לעקוב אחר פעילות גופנית. מה עושה אפליקציה למשתמשים?", "correct_reason": "allows = מאפשרת. אפליקציה מיועדת לאפשר מעקב.", "options_analysis": ["ignores = מתעלמת מ- — לא רלוונטי", "נכון! allows = מאפשרת — תואם למטרת מעקב", "forbids = אוסרת — הפוך ממטרת אפליקציה", "prevents = מונעת — הפוך ממטרת אפליקציה"]}', 1.0, -1.0, 0.25, 2, 'ai', NULL, true),
('e53c243d-ad8b-4aaa-b8bf-06be5935547a', 'sentence_completion', 'The teacher ___ the students to work in pairs for the assignment.', NULL, '[{"id": "a", "text": "refused"}, {"id": "d", "text": "forbade"}, {"id": "c", "text": "encouraged"}, {"id": "b", "text": "ignored"}]'::jsonb, 2, '{"strategy": "to work in pairs = לעבוד בזוגות. מה עושה מורה שרוצה עבודה בזוגות?", "correct_reason": "encouraged = עודדה. מורה מעודדת שיטת עבודה מסוימת.", "options_analysis": ["refused = סירבה — לא רלוונטי להוראה", "forbade = אסרה — הפוך ממטרה לעודד עבודה בזוגות", "נכון! encouraged = עודדה — מתאים לקידום שיטת עבודה", "ignored = התעלמה מ- — לא רלוונטי"]}', 1.25, -1.0, 0.25, 2, 'ai', NULL, true),
('a5ffc29b-739a-4384-b02a-e2abd809b34a', 'sentence_completion', 'The town''s population has ___ significantly over the past decade.', NULL, '[{"id": "b", "text": "disappeared"}, {"id": "d", "text": "frozen"}, {"id": "a", "text": "ignored"}, {"id": "c", "text": "grown"}]'::jsonb, 3, '{"strategy": "over the past decade = במהלך העשור האחרון. מה קורה לאוכלוסיית עיר עם הזמן?", "correct_reason": "grown = גדלה. אוכלוסיות עיר בד''כ גדלות עם הזמן.", "options_analysis": ["disappeared = נעלמה — לא הגיוני לאוכלוסייה", "frozen = קפאה — לא מתאר שינוי משמעותי", "ignored = התעלמה מ- — לא רלוונטי לאוכלוסייה", "נכון! grown = גדלה — דפוס נפוץ לאוכלוסיית עיר"]}', 1.14, -1.0, 0.25, 2, 'ai', NULL, true),
('0aff95da-9cc7-4d34-8a51-42f02dafbc8c', 'restatement', 'The concert was postponed due to the singer''s sudden illness.', NULL, '[{"id": "b", "text": "The singer''s sudden illness caused the concert to be postponed."}, {"id": "a", "text": "The concert happened as scheduled despite the illness."}, {"id": "d", "text": "The concert was postponed after it had already started."}, {"id": "c", "text": "The singer was healthy, so the concert was postponed."}]'::jsonb, 0, '{"strategy": "postponed due to = נדחה בגלל. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["נכון! אותה סיבה-תוצאה בדיוק", "סותר ''postponed''", "סותר את הרעיון שהופסק לפני שהתחיל", "סותר ''sudden illness''"]}', 1.0, -1.0, 0.25, 2, 'ai', NULL, true),
('ea2fa1f5-c14f-4763-87bf-19048cf14daf', 'restatement', 'Because the roads were icy, drivers were advised to stay home.', NULL, '[{"id": "b", "text": "Drivers were told to drive fast on the icy roads."}, {"id": "a", "text": "Drivers were advised to stay home because the roads were icy."}, {"id": "d", "text": "The roads were clear, so drivers were advised to stay home."}, {"id": "c", "text": "The roads became icy after drivers stayed home."}]'::jsonb, 1, '{"strategy": "because icy...advised = בגלל קרח...יעצו. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["סותר את העצה להישאר בבית", "נכון! אותה סיבה-תוצאה בדיוק", "הפוך — ''clear'' סותר ''icy''", "הופך את סדר האירועים"]}', 1.22, -1.0, 0.25, 2, 'ai', NULL, true),
('049fbb2a-63d3-47d3-b667-29a0323e42a9', 'restatement', 'The company launched a new website to improve customer service.', NULL, '[{"id": "b", "text": "The company closed its website to reduce customer service."}, {"id": "a", "text": "The company launched the website before it had any customers."}, {"id": "c", "text": "To improve customer service, the company launched a new website."}, {"id": "d", "text": "Customer service had no connection to the new website."}]'::jsonb, 2, '{"strategy": "launched to improve = השיקה כדי לשפר. מטרה.", "correct_reason": "אותה מטרה בדיוק.", "options_analysis": ["הפוך — ''closed'' סותר ''launched''", "לא נאמר במקור", "נכון! אותה מטרה בדיוק", "סותר את הקשר שצוין במפורש"]}', 1.3, -1.0, 0.25, 2, 'ai', NULL, true),
('00f9198c-4c2b-46d2-85ff-68d62bcf5ae9', 'restatement', 'The bakery sells out of bread every morning within an hour of opening.', NULL, '[{"id": "c", "text": "The bakery''s bread takes all day to sell out."}, {"id": "b", "text": "The bakery never sells out of bread."}, {"id": "a", "text": "The bakery closes an hour after opening."}, {"id": "d", "text": "Within an hour of opening, the bakery''s bread sells out every morning."}]'::jsonb, 3, '{"strategy": "sells out within an hour = נגמר תוך שעה. פרט זמן.", "correct_reason": "אותה עובדה בדיוק, סדר מילים הפוך.", "options_analysis": ["סותר ''within an hour''", "סותר ''sells out...every morning''", "לא נאמר במקור על סגירה", "נכון! אותה עובדה בדיוק"]}', 1.59, -1.0, 0.25, 2, 'ai', NULL, true),
('c7e717b7-d2c7-45ff-844e-89d06701c37c', 'restatement', 'The scientist repeated the experiment to confirm the initial results.', NULL, '[{"id": "d", "text": "To confirm the initial results, the scientist repeated the experiment."}, {"id": "a", "text": "The initial results were confirmed without any experiment."}, {"id": "c", "text": "The scientist performed the experiment only once."}, {"id": "b", "text": "The scientist refused to repeat the experiment."}]'::jsonb, 0, '{"strategy": "repeated to confirm = חזרה כדי לאשר. מטרה.", "correct_reason": "אותה מטרה בדיוק.", "options_analysis": ["נכון! אותה מטרה בדיוק", "סותר את קיום הניסוי החוזר", "סותר ''repeated''", "סותר ''repeated the experiment''"]}', 1.47, -1.0, 0.25, 2, 'ai', NULL, true),
('be5a0c44-8ada-4522-9587-deefa4fc9794', 'restatement', 'The airport was closed temporarily due to heavy fog.', NULL, '[{"id": "b", "text": "The airport was closed permanently due to fog."}, {"id": "a", "text": "Heavy fog caused the airport to close temporarily."}, {"id": "c", "text": "The airport remained open despite the heavy fog."}, {"id": "d", "text": "The fog appeared after the airport closed."}]'::jsonb, 1, '{"strategy": "closed temporarily due to = נסגר זמנית בגלל. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הפוך — ''permanently'' סותר ''temporarily''", "נכון! אותה סיבה-תוצאה בדיוק", "סותר ''closed temporarily''", "הופך את סדר האירועים"]}', 1.01, -1.0, 0.25, 2, 'ai', NULL, true),
('2699127c-fac1-470d-b5e4-66af5b4367fe', 'restatement', 'The company offers discounts to customers who shop online.', NULL, '[{"id": "c", "text": "The company charges extra for online shopping."}, {"id": "d", "text": "The company stopped offering any discounts."}, {"id": "a", "text": "Customers who shop online receive discounts from the company."}, {"id": "b", "text": "No customers ever shop online at this company."}]'::jsonb, 2, '{"strategy": "offers discounts to = מציעה הנחות ל-. פרט מדיניות.", "correct_reason": "אותה עובדה בדיוק, ניסוח מנקודת מבט הלקוח.", "options_analysis": ["הפוך — ''charges extra'' סותר ''offers discounts''", "סותר ''offers discounts''", "נכון! אותה עובדה בדיוק", "סותר לגמרי — יש לקוחות שקונים אונליין"]}', 1.12, -1.0, 0.25, 2, 'ai', NULL, true),
('e2128a38-8e16-4052-8727-8f3148b223d5', 'restatement', 'The museum added a new wing to display its growing art collection.', NULL, '[{"id": "d", "text": "The museum''s collection stopped growing after the new wing was built."}, {"id": "c", "text": "The art collection had no connection to the new wing."}, {"id": "a", "text": "The museum removed a wing due to its shrinking collection."}, {"id": "b", "text": "To display its growing art collection, the museum added a new wing."}]'::jsonb, 3, '{"strategy": "added a wing to display = הוסיפה אגף כדי להציג. מטרה.", "correct_reason": "אותה מטרה בדיוק.", "options_analysis": ["לא נאמר במקור", "סותר את הקשר שצוין במפורש", "הפוך — ''removed'' סותר ''added'', ו''shrinking'' סותר ''growing''", "נכון! אותה מטרה בדיוק"]}', 1.42, -1.0, 0.25, 2, 'ai', NULL, true),
('63c76516-e148-4b38-913c-5240e9b11635', 'restatement', 'The factory reduced its emissions by installing new filters.', NULL, '[{"id": "d", "text": "Installing new filters allowed the factory to reduce its emissions."}, {"id": "c", "text": "Emissions had no connection to the new filters."}, {"id": "b", "text": "The factory increased its emissions after installing filters."}, {"id": "a", "text": "The factory refused to install any filters."}]'::jsonb, 0, '{"strategy": "reduced emissions by installing = הפחיתה פליטות ע''י התקנת. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["נכון! אותה סיבה-תוצאה בדיוק", "סותר את הקשר שצוין במפורש", "הפוך — ''increased'' סותר ''reduced''", "סותר לגמרי — הם כן התקינו מסננים"]}', 0.91, -1.0, 0.25, 2, 'ai', NULL, true),
('e3db75b2-ee9a-48b9-85eb-3c094f265bcf', 'restatement', 'The city built a new bridge to connect the two neighborhoods.', NULL, '[{"id": "d", "text": "The city demolished the bridge to separate the neighborhoods."}, {"id": "a", "text": "To connect the two neighborhoods, the city built a new bridge."}, {"id": "c", "text": "The two neighborhoods have never been connected."}, {"id": "b", "text": "The bridge was built before the neighborhoods existed."}]'::jsonb, 1, '{"strategy": "built to connect = בנתה כדי לחבר. מטרה.", "correct_reason": "אותה מטרה בדיוק.", "options_analysis": ["הפוך — ''demolished'' סותר ''built''", "נכון! אותה מטרה בדיוק", "סותר לגמרי — הגשר כן חיבר אותן", "לא נאמר במקור סדר כזה"]}', 1.56, -1.0, 0.25, 2, 'ai', NULL, true),
('5efe1348-e0c2-4e5c-aadf-9623e37ef677', 'restatement', 'The store hired extra staff to handle the holiday rush.', NULL, '[{"id": "d", "text": "There was no increase in customers during the holidays."}, {"id": "c", "text": "The store hired staff after the holiday season ended."}, {"id": "a", "text": "To handle the holiday rush, the store hired extra staff."}, {"id": "b", "text": "The store fired staff during the holiday rush."}]'::jsonb, 2, '{"strategy": "hired extra staff to handle = שכרה צוות נוסף כדי לטפל. מטרה.", "correct_reason": "אותה מטרה בדיוק.", "options_analysis": ["סותר ''holiday rush''", "סותר את התזמון — הגיוס היה לקראת החגים", "נכון! אותה מטרה בדיוק", "הפוך — ''fired'' סותר ''hired''"]}', 1.04, -1.0, 0.25, 2, 'ai', NULL, true),
('7e38d82d-3048-4c57-9c93-a0b073b44a73', 'restatement', 'The theater canceled the show because ticket sales were too low.', NULL, '[{"id": "b", "text": "The show was canceled after it had already ended."}, {"id": "d", "text": "Ticket sales were extremely high for the show."}, {"id": "c", "text": "The theater canceled the show despite excellent ticket sales."}, {"id": "a", "text": "Because ticket sales were too low, the theater canceled the show."}]'::jsonb, 3, '{"strategy": "canceled because low sales = בוטל בגלל מכירות נמוכות. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הופך את סדר האירועים", "סותר ''too low'' — המכירות היו נמוכות, לא גבוהות", "סותר ''too low''", "נכון! אותה סיבה-תוצאה בדיוק"]}', 1.23, -1.0, 0.25, 2, 'ai', NULL, true),
('6b480064-df82-46c2-94e2-eaca49e6cc1e', 'reading_comprehension', 'What is the passage mainly about?', '3eaf782c-dfda-4fca-a9f2-09089fbc7306', '[{"id": "c", "text": "Schools introducing coding classes and the debate around them"}, {"id": "a", "text": "The history of computer science"}, {"id": "d", "text": "How to become a professional programmer"}, {"id": "b", "text": "Why art classes are unnecessary"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה עוסקת בהכנסת שיעורי תכנות לבתי ספר והדעות השונות על כך.", "correct_reason": "כל הפסקה סוקרת את מגמת שיעורי התכנות, יתרונותיה והביקורת עליה.", "options_analysis": ["נכון! מגמת שיעורי התכנות והוויכוח סביבה = הנושא הכולל", "לא מוזכר בפסקה כלל", "לא הוראות מקצועיות, אלא ניתוח חינוכי", "הפוך — הפסקה לא טוענת עמדה כזו"]}', 1.05, -1.0, 0.25, 2, 'ai', NULL, true),
('83ff50cb-ae00-4da6-b8fe-313ea35b7d55', 'reading_comprehension', 'According to supporters, what skills does coding help children develop?', '3eaf782c-dfda-4fca-a9f2-09089fbc7306', '[{"id": "b", "text": "Only physical fitness"}, {"id": "d", "text": "Problem-solving skills and logical thinking"}, {"id": "c", "text": "Foreign language skills"}, {"id": "a", "text": "Only artistic skills"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את הטיעון של התומכים בפסקה.", "correct_reason": "הפסקה אומרת: ''learning to code helps children develop problem-solving skills and logical thinking''.", "options_analysis": ["לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.38, -1.0, 0.25, 2, 'ai', NULL, true),
('71798b50-9e9a-4b86-8094-35c933e40c21', 'reading_comprehension', 'The word "debugging" in the passage most closely means:', '3eaf782c-dfda-4fca-a9f2-09089fbc7306', '[{"id": "a", "text": "deleting an entire program"}, {"id": "d", "text": "writing a program from scratch"}, {"id": "c", "text": "identifying and fixing errors in a program"}, {"id": "b", "text": "translating a program into another language"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''a process often called debugging'' מתייחס לתיקון שגיאות.", "correct_reason": "debugging = תהליך איתור ותיקון שגיאות בתוכנית.", "options_analysis": ["לא קשור למשמעות המילה", "לא קשור למשמעות המילה — זו כתיבה, לא תיקון", "נכון! debugging = איתור ותיקון שגיאות", "לא קשור למשמעות המילה"]}', 1.31, -1.0, 0.25, 2, 'ai', NULL, true),
('3869a38e-ef7d-432f-b456-1e4d5a6e9889', 'reading_comprehension', 'What concern do critics raise about coding classes, according to the passage?', '3eaf782c-dfda-4fca-a9f2-09089fbc7306', '[{"id": "d", "text": "That coding classes are illegal in some countries"}, {"id": "a", "text": "That coding is impossible to teach to children"}, {"id": "c", "text": "That no school has ever tried teaching coding"}, {"id": "b", "text": "That they take time away from other important subjects"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את החשש שמעלים מבקרים בפסקה.", "correct_reason": "הפסקה אומרת: ''critics...worry that adding coding classes takes time away from other important subjects''.", "options_analysis": ["לא נאמר בפסקה", "לא נאמר בפסקה, וסותר את כל הפסקה", "סותר את הפסקה — בתי ספר רבים כן מנסים", "נכון! נאמר במפורש בפסקה"]}', 1.46, -1.0, 0.25, 2, 'ai', NULL, true),
('20471875-8833-4661-a372-d34eca48c809', 'reading_comprehension', 'How have some schools addressed the concern about limited class hours, according to the passage?', '3eaf782c-dfda-4fca-a9f2-09089fbc7306', '[{"id": "b", "text": "By integrating basic coding concepts into existing subjects like math and science"}, {"id": "c", "text": "By extending the school day by several hours"}, {"id": "d", "text": "By canceling all coding classes entirely"}, {"id": "a", "text": "By removing math and science from the curriculum"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את הפתרון שמוצע בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''some schools have chosen to integrate basic coding concepts into existing subjects, such as math and science''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "סותר את הפסקה — הן דווקא משלבות, לא מבטלות", "סותר את הפסקה — התכנות משולב בהם, לא מחליף אותם"]}', 1.3, -1.0, 0.25, 2, 'ai', NULL, true);